function travel_flight_table_insert(&$error_message = '') {
	global $Translation;

	// mm: can member insert record?
	$arrPerm = getTablePermissions('travel_flight_table');
	if(!$arrPerm['insert']) {
		$error_message = $Translation['no insert permission'];
		return false;
	}

	// automatic travel_details if passed as filterer
	if(Request::val('filterer_travel_details')) {
		$_REQUEST['travel_details'] = Request::val('filterer_travel_details');
	}

	$data = [
		'flight_number' => Request::val('flight_number', ''),
		'travel_date' => Request::dateComponents('travel_date', '1'),
		'flight_time' => Request::val('flight_time', ''),
		'from' => Request::val('from', ''),
		'to' => Request::val('to', ''),
		'seat_preferance' => Request::val('seat_preferance', ''),
		'status' => Request::val('status', ''),
		'remarks' => br2nl(Request::val('remarks', '')),
		'created_by' => parseCode('<%%creatorUsername%%>', true),
		'created_at' => parseCode('<%%creationDateTime%%>', true),
	];


	// automatic travel_details if passed as filterer
	if(Request::val('filterer_travel_details')) {
		$data['travel_details'] = Request::val('filterer_travel_details');
	}
	// record owner is current user
	$recordOwner = getLoggedMemberID();

	$recID = tableInsert('travel_flight_table', $data, $recordOwner, $error_message);

	// if this record is a copy of another record, copy children if applicable
	if(strlen(Request::val('SelectedID')) && $recID !== false)
		travel_flight_table_copy_children($recID, Request::val('SelectedID'));

	return $recID;
}

function travel_flight_table_copy_children($destination_id, $source_id) {
	global $Translation;
	$requests = []; // array of curl handlers for launching insert requests
	$eo = ['silentErrors' => true];
	$safe_sid = makeSafe($source_id);
	$currentUsername = getLoggedMemberID();
	$errorMessage = '';

	// launch requests, asynchronously
	curl_batch($requests);
}

function travel_flight_table_delete($selected_id, $AllowDeleteOfParents = false, $skipChecks = false) {
	// insure referential integrity ...
	global $Translation;
	$selected_id = makeSafe($selected_id);

	// mm: can member delete record?
	if(!check_record_permission('travel_flight_table', $selected_id, 'delete')) {
		return $Translation['You don\'t have enough permissions to delete this record'];
	}

	// hook: travel_flight_table_before_delete
	if(function_exists('travel_flight_table_before_delete')) {
		$args = [];
		if(!travel_flight_table_before_delete($selected_id, $skipChecks, getMemberInfo(), $args))
			return $Translation['Couldn\'t delete this record'] . (
				!empty($args['error_message']) ?
					'<div class="text-bold">' . strip_tags($args['error_message']) . '</div>'
					: '' 
			);
	}

	sql("DELETE FROM `travel_flight_table` WHERE `id`='{$selected_id}'", $eo);

	// hook: travel_flight_table_after_delete
	if(function_exists('travel_flight_table_after_delete')) {
		$args = [];
		travel_flight_table_after_delete($selected_id, getMemberInfo(), $args);
	}

	// mm: delete ownership data
	sql("DELETE FROM `membership_userrecords` WHERE `tableName`='travel_flight_table' AND `pkValue`='{$selected_id}'", $eo);
}

function travel_flight_table_update(&$selected_id, &$error_message = '') {
	global $Translation;

	// mm: can member edit record?
	if(!check_record_permission('travel_flight_table', $selected_id, 'edit')) return false;

	$data = [
		'flight_number' => Request::val('flight_number', ''),
		'travel_date' => Request::dateComponents('travel_date', ''),
		'flight_time' => Request::val('flight_time', ''),
		'from' => Request::val('from', ''),
		'to' => Request::val('to', ''),
		'seat_preferance' => Request::val('seat_preferance', ''),
		'status' => Request::val('status', ''),
		'remarks' => br2nl(Request::val('remarks', '')),
		'last_updated_by' => parseCode('<%%editorUsername%%>', false),
		'last_updated_at' => parseCode('<%%editingDateTime%%>', false),
	];

	// get existing values
	$old_data = getRecord('travel_flight_table', $selected_id);
	if(is_array($old_data)) {
		$old_data = array_map('makeSafe', $old_data);
		$old_data['selectedID'] = makeSafe($selected_id);
	}

	$data['selectedID'] = makeSafe($selected_id);

	// hook: travel_flight_table_before_update
	if(function_exists('travel_flight_table_before_update')) {
		$args = ['old_data' => $old_data];
		if(!travel_flight_table_before_update($data, getMemberInfo(), $args)) {
			if(isset($args['error_message'])) $error_message = $args['error_message'];
			return false;
		}
	}

	$set = $data; unset($set['selectedID']);
	foreach ($set as $field => $value) {
		$set[$field] = ($value !== '' && $value !== NULL) ? $value : NULL;
	}

	if(!update(
		'travel_flight_table', 
		backtick_keys_once($set), 
		['`id`' => $selected_id], 
		$error_message
	)) {
		echo $error_message;
		echo '<a href="travel_flight_table_view.php?SelectedID=' . urlencode($selected_id) . "\">{$Translation['< back']}</a>";
		exit;
	}


	update_calc_fields('travel_flight_table', $data['selectedID'], calculated_fields()['travel_flight_table']);

	// hook: travel_flight_table_after_update
	if(function_exists('travel_flight_table_after_update')) {
		if($row = getRecord('travel_flight_table', $data['selectedID'])) $data = array_map('makeSafe', $row);

		$data['selectedID'] = $data['id'];
		$args = ['old_data' => $old_data];
		if(!travel_flight_table_after_update($data, getMemberInfo(), $args)) return;
	}

	// mm: update record update timestamp
	set_record_owner('travel_flight_table', $selected_id);
}

