	$templateCode = str_replace('<%%UPLOADFILE(travel_details)%%>', '', $templateCode);
	$templateCode = str_replace('<%%UPLOADFILE(flight_number)%%>', '', $templateCode);
	$templateCode = str_replace('<%%UPLOADFILE(travel_date)%%>', '', $templateCode);
	$templateCode = str_replace('<%%UPLOADFILE(flight_time)%%>', '', $templateCode);
	$templateCode = str_replace('<%%UPLOADFILE(from)%%>', '', $templateCode);
	$templateCode = str_replace('<%%UPLOADFILE(to)%%>', '', $templateCode);
	$templateCode = str_replace('<%%UPLOADFILE(seat_preferance)%%>', '', $templateCode);
	$templateCode = str_replace('<%%UPLOADFILE(status)%%>', '', $templateCode);
	$templateCode = str_replace('<%%UPLOADFILE(remarks)%%>', '', $templateCode);
	$templateCode = str_replace('<%%UPLOADFILE(created_by)%%>', '', $templateCode);
