	$templateCode = str_replace('<%%UPLOADFILE(last_updated_by)%%>', '', $templateCode);
	$templateCode = str_replace('<%%UPLOADFILE(last_updated_at)%%>', '', $templateCode);

	// process values
	if($hasSelectedId) {
		$templateCode = str_replace('<%%VALUE(id)%%>', safe_html($urow['id']), $templateCode);
		$templateCode = str_replace('<%%URLVALUE(id)%%>', urlencode($urow['id']), $templateCode);
		$templateCode = str_replace('<%%VALUE(travel_details)%%>', safe_html($urow['travel_details']), $templateCode);
		$templateCode = str_replace('<%%URLVALUE(travel_details)%%>', urlencode($urow['travel_details']), $templateCode);
		if( $dvprint) $templateCode = str_replace('<%%VALUE(flight_number)%%>', safe_html($urow['flight_number']), $templateCode);
		if(!$dvprint) $templateCode = str_replace('<%%VALUE(flight_number)%%>', html_attr($row['flight_number']), $templateCode);
		$templateCode = str_replace('<%%URLVALUE(flight_number)%%>', urlencode($urow['flight_number']), $templateCode);
		$templateCode = str_replace('<%%VALUE(travel_date)%%>', app_datetime($row['travel_date']), $templateCode);
		$templateCode = str_replace('<%%URLVALUE(travel_date)%%>', urlencode(app_datetime($urow['travel_date'])), $templateCode);
		if( $dvprint) $templateCode = str_replace('<%%VALUE(flight_time)%%>', safe_html($urow['flight_time']), $templateCode);
		if(!$dvprint) $templateCode = str_replace('<%%VALUE(flight_time)%%>', html_attr($row['flight_time']), $templateCode);
		$templateCode = str_replace('<%%URLVALUE(flight_time)%%>', urlencode($urow['flight_time']), $templateCode);
		if( $dvprint) $templateCode = str_replace('<%%VALUE(from)%%>', safe_html($urow['from']), $templateCode);
		if(!$dvprint) $templateCode = str_replace('<%%VALUE(from)%%>', html_attr($row['from']), $templateCode);
		$templateCode = str_replace('<%%URLVALUE(from)%%>', urlencode($urow['from']), $templateCode);
		if( $dvprint) $templateCode = str_replace('<%%VALUE(to)%%>', safe_html($urow['to']), $templateCode);
		if(!$dvprint) $templateCode = str_replace('<%%VALUE(to)%%>', html_attr($row['to']), $templateCode);
		$templateCode = str_replace('<%%URLVALUE(to)%%>', urlencode($urow['to']), $templateCode);
		if( $dvprint) $templateCode = str_replace('<%%VALUE(seat_preferance)%%>', safe_html($urow['seat_preferance']), $templateCode);
		if(!$dvprint) $templateCode = str_replace('<%%VALUE(seat_preferance)%%>', html_attr($row['seat_preferance']), $templateCode);
		$templateCode = str_replace('<%%URLVALUE(seat_preferance)%%>', urlencode($urow['seat_preferance']), $templateCode);
		if( $dvprint) $templateCode = str_replace('<%%VALUE(status)%%>', safe_html($urow['status']), $templateCode);
		if(!$dvprint) $templateCode = str_replace('<%%VALUE(status)%%>', html_attr($row['status']), $templateCode);
		$templateCode = str_replace('<%%URLVALUE(status)%%>', urlencode($urow['status']), $templateCode);
		$templateCode = str_replace('<%%VALUE(remarks)%%>', safe_html($urow['remarks'], $fieldsAreEditable), $templateCode);
		$templateCode = str_replace('<%%URLVALUE(remarks)%%>', urlencode($urow['remarks']), $templateCode);
		$templateCode = str_replace('<%%VALUE(created_by)%%>', safe_html($urow['created_by']), $templateCode);
		$templateCode = str_replace('<%%URLVALUE(created_by)%%>', urlencode($urow['created_by']), $templateCode);
		$templateCode = str_replace('<%%VALUE(created_at)%%>', safe_html($urow['created_at']), $templateCode);
		$templateCode = str_replace('<%%URLVALUE(created_at)%%>', urlencode($urow['created_at']), $templateCode);
		$templateCode = str_replace('<%%VALUE(last_updated_by)%%>', safe_html($urow['last_updated_by']), $templateCode);
		$templateCode = str_replace('<%%URLVALUE(last_updated_by)%%>', urlencode($urow['last_updated_by']), $templateCode);
		$templateCode = str_replace('<%%VALUE(last_updated_at)%%>', safe_html($urow['last_updated_at']), $templateCode);
		$templateCode = str_replace('<%%URLVALUE(last_updated_at)%%>', urlencode($urow['last_updated_at']), $templateCode);
	} else {
		$templateCode = str_replace('<%%VALUE(id)%%>', '', $templateCode);
		$templateCode = str_replace('<%%URLVALUE(id)%%>', urlencode(''), $templateCode);
		$templateCode = str_replace('<%%VALUE(travel_details)%%>', '', $templateCode);
		$templateCode = str_replace('<%%URLVALUE(travel_details)%%>', urlencode(''), $templateCode);
		$templateCode = str_replace('<%%VALUE(flight_number)%%>', '', $templateCode);
		$templateCode = str_replace('<%%URLVALUE(flight_number)%%>', urlencode(''), $templateCode);
		$templateCode = str_replace('<%%VALUE(travel_date)%%>', '1', $templateCode);
		$templateCode = str_replace('<%%URLVALUE(travel_date)%%>', urlencode('1'), $templateCode);
		$templateCode = str_replace('<%%VALUE(flight_time)%%>', '', $templateCode);
		$templateCode = str_replace('<%%URLVALUE(flight_time)%%>', urlencode(''), $templateCode);
		$templateCode = str_replace('<%%VALUE(from)%%>', '', $templateCode);
		$templateCode = str_replace('<%%URLVALUE(from)%%>', urlencode(''), $templateCode);
		$templateCode = str_replace('<%%VALUE(to)%%>', '', $templateCode);
		$templateCode = str_replace('<%%URLVALUE(to)%%>', urlencode(''), $templateCode);
		$templateCode = str_replace('<%%VALUE(seat_preferance)%%>', '', $templateCode);
		$templateCode = str_replace('<%%URLVALUE(seat_preferance)%%>', urlencode(''), $templateCode);
		$templateCode = str_replace('<%%VALUE(status)%%>', '', $templateCode);
		$templateCode = str_replace('<%%URLVALUE(status)%%>', urlencode(''), $templateCode);
		$templateCode = str_replace('<%%VALUE(remarks)%%>', '', $templateCode);
		$templateCode = str_replace('<%%URLVALUE(remarks)%%>', urlencode(''), $templateCode);
		$templateCode = str_replace('<%%VALUE(created_by)%%>', '<%%creatorUsername%%>', $templateCode);
		$templateCode = str_replace('<%%URLVALUE(created_by)%%>', urlencode('<%%creatorUsername%%>'), $templateCode);
		$templateCode = str_replace('<%%VALUE(created_at)%%>', '<%%creationDateTime%%>', $templateCode);
		$templateCode = str_replace('<%%URLVALUE(created_at)%%>', urlencode('<%%creationDateTime%%>'), $templateCode);
		$templateCode = str_replace('<%%VALUE(last_updated_by)%%>', '<%%editorUsername%%>', $templateCode);
		$templateCode = str_replace('<%%URLVALUE(last_updated_by)%%>', urlencode('<%%editorUsername%%>'), $templateCode);
		$templateCode = str_replace('<%%VALUE(last_updated_at)%%>', '<%%editingDateTime%%>', $templateCode);
		$templateCode = str_replace('<%%URLVALUE(last_updated_at)%%>', urlencode('<%%editingDateTime%%>'), $templateCode);
	}

	// process translations
	$templateCode = parseTemplate($templateCode);

	// clear scrap
	$templateCode = str_replace('<%%', '<!-- ', $templateCode);
	$templateCode = str_replace('%%>', ' -->', $templateCode);

	// hide links to inaccessible tables
	if(Request::val('dvprint_x') == '') {
		$templateCode .= "\n\n<script>\$j(function() {\n";
		$arrTables = getTableList();
		foreach($arrTables as $name => $caption) {
			$templateCode .= "\t\$j('#{$name}_link').removeClass('hidden');\n";
			$templateCode .= "\t\$j('#xs_{$name}_link').removeClass('hidden');\n";
		}

		$templateCode .= $jsReadOnly;
		$templateCode .= $jsEditable;

		if(!$hasSelectedId) {
		}

		$templateCode.="\n});</script>\n";
	}

	// ajaxed auto-fill fields
	$templateCode .= '<script>';
	$templateCode .= '$j(function() {';


	$templateCode.="});";
	$templateCode.="</script>";
	$templateCode .= $lookups;

	// handle enforced parent values for read-only lookup fields
	$filterField = Request::val('FilterField');
	$filterOperator = Request::val('FilterOperator');
	$filterValue = Request::val('FilterValue');
	if(isset($filterField[1]) && $filterField[1] == '2' && $filterOperator[1] == '<=>')
		$templateCode.="\n<input type=hidden name=travel_details value=\"" . html_attr($filterValue[1]) . "\">\n";

	// don't include blank images in lightbox gallery
	$templateCode = preg_replace('/blank.gif" data-lightbox=".*?"/', 'blank.gif"', $templateCode);

	// don't display empty email links
	$templateCode=preg_replace('/<a .*?href="mailto:".*?<\/a>/', '', $templateCode);

	/* default field values */
	$rdata = $jdata = get_defaults('travel_flight_table');
	if($hasSelectedId) {
		$jdata = get_joined_record('travel_flight_table', $selectedId);
		if($jdata === false) $jdata = get_defaults('travel_flight_table');
		$rdata = $row;
	}
	$templateCode .= loadView('travel_flight_table-ajax-cache', ['rdata' => $rdata, 'jdata' => $jdata]);

	// hook: travel_flight_table_dv
	if(function_exists('travel_flight_table_dv')) {
		$args = [];
		travel_flight_table_dv(($hasSelectedId ? $selectedId : FALSE), getMemberInfo(), $templateCode, $args);
	}

	return $templateCode;
}